package com.example.graphql

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.routing.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.http.*
import java.sql.Connection
import java.sql.DriverManager
import java.sql.ResultSet
import com.google.gson.Gson
import com.google.gson.JsonParser

data class GraphQLRequest(val query: String, val variables: Map<String, Any>? = null)
data class GraphQLResponse(val data: Any? = null, val errors: List<Map<String, Any>>? = null)

class UserRepository(private val dbUrl: String, private val dbUser: String, private val dbPass: String) {
    private fun getConnection(): Connection {
        return DriverManager.getConnection(dbUrl, dbUser, dbPass)
    }

    fun resolveQuery(query: String): Any {
        // Parse GraphQL query and extract field selections
        val fieldMatch = Regex("""\{\s*(\w+)\s*\((.+?)\)\s*\{(.+?)\}\s*\}""").find(query)
        if (fieldMatch == null) return mapOf("error" to "Invalid query format")

        val resolver = fieldMatch.groupValues[1]
        val args = fieldMatch.groupValues[2]
        val fields = fieldMatch.groupValues[3].trim().split(Regex("\\s+"))

        return when (resolver) {
            "user" -> resolveUser(args, fields)
            "users" -> resolveUsers(args, fields)
            "userActivity" -> resolveUserActivity(args, fields)
            else -> mapOf("error" to "Unknown resolver: $resolver")
        }
    }

    private fun resolveUser(args: String, fields: List<String>): Any {
        val idMatch = Regex("""id:\s*"(.+?)"""").find(args)
        val id = idMatch?.groupValues?.get(1) ?: return mapOf("error" to "Missing id")

        // Direct string interpolation - vulnerable to injection
        val sql = "SELECT ${fields.joinToString(", ")} FROM users WHERE id = '$id'"
        return executeQuery(sql, fields)
    }

    private fun resolveUsers(args: String, fields: List<String>): Any {
        val filterMatch = Regex("""filter:\s*"(.+?)"""").find(args)
        val filter = filterMatch?.groupValues?.get(1) ?: "1=1"

        val limitMatch = Regex("""limit:\s*(\d+)""").find(args)
        val limit = limitMatch?.groupValues?.get(1) ?: "50"

        // Vulnerable: filter is directly interpolated
        val sql = "SELECT ${fields.joinToString(", ")} FROM users WHERE $filter LIMIT $limit"
        return executeQuery(sql, fields)
    }

    private fun resolveUserActivity(args: String, fields: List<String>): Any {
        val userIdMatch = Regex("""userId:\s*"(.+?)"""").find(args)
        val userId = userIdMatch?.groupValues?.get(1) ?: return mapOf("error" to "Missing userId")

        // Also vulnerable - userId not sanitized
        val sql = "SELECT ${fields.joinToString(", ")} FROM user_activity WHERE user_id = '$userId' ORDER BY timestamp DESC"
        return executeQuery(sql, fields)
    }

    private fun executeQuery(sql: String, fields: List<String>): List<Map<String, Any?>> {
        val results = mutableListOf<Map<String, Any?>>()
        getConnection().use { conn ->
            conn.createStatement().use { stmt ->
                val rs = stmt.executeQuery(sql)
                while (rs.next()) {
                    val row = mutableMapOf<String, Any?>()
                    for (field in fields) {
                        try {
                            row[field] = rs.getObject(field)
                        } catch (e: Exception) {
                            row[field] = null
                        }
                    }
                    results.add(row)
                }
            }
        }
        return results
    }
}

fun main() {
    val dbUrl = System.getenv("DATABASE_URL") ?: "jdbc:postgresql://localhost:5432/appdb"
    val dbUser = System.getenv("DATABASE_USER") ?: "app_readonly"
    val dbPass = System.getenv("DATABASE_PASSWORD") ?: "secret"
    val repo = UserRepository(dbUrl, dbUser, dbPass)
    val gson = Gson()

    embeddedServer(Netty, port = 8080) {
        routing {
            post("/graphql") {
                val body = call.receiveText()
                val request = gson.fromJson(body, GraphQLRequest::class.java)

                val result = try {
                    repo.resolveQuery(request.query)
                } catch (e: Exception) {
                    mapOf("error" to e.message)
                }

                val response = GraphQLResponse(data = result)
                call.respondText(gson.toJson(response), ContentType.Application.Json)
            }
        }
    }.start(wait = true)
}
